INSERT INTO changelog (title, body, created_at) VALUES ('Список клієнтів — як в App Store', 'Кожен клієнт у списку: лого, назва, один рядок опису (вид бізнесу), скільки платить / частка і одна головна мітка проблеми (+N — ще скільки; наведи — побачиш усі). Довгі описи, наступний крок і купа міток — тільки в картці клієнта.', datetime('now'));
